CREATE FUNCTION public.find_people(_search text) RETURNS TABLE(id uuid,name text,verified boolean,interests text[]) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,split_part(p.name,' ',1),p.verified,p.interests FROM public.profiles p WHERE auth.uid() IS NOT NULL AND p.id<>auth.uid() AND p.onboarded AND NOT public.people_blocked(auth.uid(),p.id) AND (p.name ILIKE '%'||left(_search,80)||'%' OR EXISTS(SELECT 1 FROM unnest(p.interests) i WHERE i ILIKE '%'||left(_search,80)||'%')) LIMIT 30 $$; REVOKE ALL ON FUNCTION public.find_people(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.find_people(text) TO authenticated;
ALTER TABLE public.plans ADD COLUMN is_private boolean NOT NULL DEFAULT false, ADD COLUMN private_participants uuid[] NOT NULL DEFAULT '{}';
ALTER POLICY "plans are public" ON public.plans USING(NOT is_private);
CREATE POLICY "private plan participants read" ON public.plans FOR SELECT TO authenticated USING(host_id=auth.uid() OR (is_private AND auth.uid()=ANY(private_participants)));
CREATE TABLE public.hang_proposals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sender uuid NOT NULL REFERENCES public.profiles(id),recipient uuid NOT NULL REFERENCES public.profiles(id),activity text NOT NULL DEFAULT '',window_label text NOT NULL DEFAULT 'this week',starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,time_of_day text NOT NULL DEFAULT 'any',status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','accepted','suggested','declined')),suggestion text NOT NULL DEFAULT '',plan_id uuid REFERENCES public.plans(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(sender<>recipient),CHECK(ends_at>=starts_at));
GRANT SELECT,INSERT ON public.hang_proposals TO authenticated; GRANT ALL ON public.hang_proposals TO service_role; ALTER TABLE public.hang_proposals ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.shared_plan_count(a uuid,b uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*)::integer FROM public.plans p WHERE p.starts_at<now() AND public.is_plan_member(p.id,a) AND public.is_plan_member(p.id,b) $$; REVOKE ALL ON FUNCTION public.shared_plan_count(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.shared_plan_count(uuid,uuid) TO authenticated,service_role;
CREATE POLICY "proposal participants read" ON public.hang_proposals FOR SELECT TO authenticated USING((sender=auth.uid() OR recipient=auth.uid()) AND NOT public.people_blocked(sender,recipient));
CREATE POLICY "eligible people propose" ON public.hang_proposals FOR INSERT TO authenticated WITH CHECK(sender=auth.uid() AND status='pending' AND plan_id IS NULL AND starts_at>now() AND NOT public.people_blocked(sender,recipient) AND (public.shared_plan_count(sender,recipient)>=2 OR (public.are_friends(sender,recipient) AND public.shared_plan_count(sender,recipient)>=1)));
CREATE FUNCTION public.hang_candidates() RETURNS TABLE(person_id uuid,name text,title text,last_met timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,split_part(p.name,' ',1),last_plan.title,last_plan.starts_at FROM public.profiles p CROSS JOIN LATERAL(SELECT x.title,x.starts_at FROM public.plans x WHERE x.starts_at<now() AND public.is_plan_member(x.id,auth.uid()) AND public.is_plan_member(x.id,p.id) ORDER BY x.starts_at DESC LIMIT 1) last_plan WHERE auth.uid() IS NOT NULL AND p.id<>auth.uid() AND NOT public.people_blocked(auth.uid(),p.id) AND (public.shared_plan_count(auth.uid(),p.id)>=2 OR (public.are_friends(auth.uid(),p.id) AND public.shared_plan_count(auth.uid(),p.id)>=1)) AND COALESCE((SELECT hang_frequency FROM public.user_settings WHERE user_id=auth.uid()),'monthly')<>'never' AND NOT EXISTS(SELECT 1 FROM public.hang_proposals h WHERE h.sender=auth.uid() AND h.recipient=p.id AND (h.status IN('pending','suggested') OR h.created_at>now()-CASE WHEN (SELECT hang_frequency FROM public.user_settings WHERE user_id=auth.uid())='every_2_months' THEN interval '2 months' ELSE interval '1 month' END)) LIMIT 8 $$; REVOKE ALL ON FUNCTION public.hang_candidates() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.hang_candidates() TO authenticated;
CREATE FUNCTION public.respond_proposal(_id uuid,_action text,_suggestion text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h public.hang_proposals; pid uuid;city_value text; BEGIN SELECT * INTO h FROM public.hang_proposals WHERE id=_id AND recipient=auth.uid() FOR UPDATE; IF h.id IS NULL OR h.status NOT IN('pending','suggested') OR public.people_blocked(h.sender,h.recipient) OR _action NOT IN('accepted','suggested','declined') THEN RAISE EXCEPTION 'Proposal unavailable'; END IF; IF _action='accepted' THEN IF h.starts_at<=now() THEN RAISE EXCEPTION 'This time window has passed. Suggest another time.'; END IF; SELECT home_city INTO city_value FROM public.profiles WHERE id=h.sender; INSERT INTO public.plans(host_id,title,category,activity,area_label,city,starts_at,capacity,description,is_private,private_participants,base_going,going_count) VALUES(h.sender,COALESCE(NULLIF(h.activity,''),'Catch up')||' with a friend',COALESCE(NULLIF(h.activity,''),'catch up'),COALESCE(NULLIF(h.activity,''),'catch up'),'Public place to agree',COALESCE(city_value,'Paris'),h.starts_at,2,'Private catch-up. Agree the public place together before you go.',true,ARRAY[h.sender,h.recipient],2,2) RETURNING id INTO pid; END IF; UPDATE public.hang_proposals SET status=_action,suggestion=left(_suggestion,1000),plan_id=pid WHERE id=h.id; RETURN pid; END $$; REVOKE ALL ON FUNCTION public.respond_proposal(uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.respond_proposal(uuid,text,text) TO authenticated;
CREATE TABLE public.profile_shares(user_id uuid PRIMARY KEY REFERENCES public.profiles(id),token uuid UNIQUE NOT NULL DEFAULT gen_random_uuid(),audience text NOT NULL DEFAULT 'friends' CHECK(audience IN('friends','link')),enabled boolean NOT NULL DEFAULT true); GRANT SELECT,INSERT,UPDATE ON public.profile_shares TO authenticated; GRANT ALL ON public.profile_shares TO service_role; ALTER TABLE public.profile_shares ENABLE ROW LEVEL SECURITY; CREATE POLICY "own profile share" ON public.profile_shares FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.shared_profile_plans(_token uuid) RETURNS TABLE(id uuid,title text,area_label text,city text,starts_at timestamptz,image_url text,owner_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.title,p.area_label,p.city,p.starts_at,p.image_url,split_part(pr.name,' ',1) FROM public.profile_shares s JOIN public.profiles pr ON pr.id=s.user_id JOIN public.plans p ON public.is_plan_member(p.id,s.user_id) WHERE s.token=_token AND s.enabled AND NOT p.is_private AND p.starts_at>now() AND (s.audience='link' OR s.user_id=auth.uid() OR public.are_friends(s.user_id,auth.uid())) AND (auth.uid() IS NULL OR NOT public.people_blocked(auth.uid(),s.user_id)) $$; REVOKE ALL ON FUNCTION public.shared_profile_plans(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.shared_profile_plans(uuid) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.notify_plan_alerts() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.is_private THEN RETURN NEW; END IF; INSERT INTO public.notifications(user_id,plan_id,alert_id,title) SELECT a.user_id,NEW.id,a.id,a.name||': '||NEW.title FROM public.saved_alerts a WHERE a.user_id IS DISTINCT FROM NEW.host_id AND NOT public.people_blocked(a.user_id,NEW.host_id) AND NEW.starts_at>now() AND public.alert_matches(NEW,a.filters) AND (COALESCE(a.filters->>'level','')='' OR EXISTS(SELECT 1 FROM public.user_settings s WHERE s.user_id=a.user_id AND s.demo_plus)); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.public_host(_id uuid) RETURNS TABLE(name text,verified boolean,reliability_score integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT split_part(p.name,' ',1),p.verified,p.reliability_score FROM public.profiles p WHERE p.id=_id AND EXISTS(SELECT 1 FROM public.plans WHERE host_id=_id AND NOT is_private) $$;